using AfriWallet.Fraud.DeviceRisk.Api.Contracts;using AfriWallet.Fraud.DeviceRisk.Application.Abstractions;using AfriWallet.Fraud.DeviceRisk.Application.Policies;using AfriWallet.Fraud.DeviceRisk.Application.Services;using AfriWallet.Fraud.DeviceRisk.Infrastructure;
var builder=WebApplication.CreateBuilder(args);builder.Services.AddSingleton<SandboxFraudSignalReader>();builder.Services.AddSingleton<IFraudSignalReader>(sp=>sp.GetRequiredService<SandboxFraudSignalReader>());builder.Services.AddSingleton<IDeviceRiskRepository,InMemoryDeviceRiskRepository>();builder.Services.AddSingleton<IDeviceRiskAuditStore,InMemoryDeviceRiskAuditStore>();builder.Services.AddSingleton<IDeviceRiskClock,SystemDeviceRiskClock>();builder.Services.AddSingleton<DeviceRiskPolicy>();builder.Services.AddSingleton<DeviceAccountRiskService>();var app=builder.Build();const string Actor="afriwallet-fraud-system";app.MapGet("/health",()=>Results.Ok(new{status="Healthy",delivery="AFW-DLV-0017.2",decisioning="RECOMMENDATION ONLY"}));app.MapPost("/api/v1/fraud/device-risk/calculate",async(CalculateDeviceRiskRequest r,DeviceAccountRiskService s,CancellationToken ct)=>Results.Ok(await s.CalculateAsync(new(r.Awid,r.DeviceId,Actor),ct)));app.MapGet("/api/v1/fraud/device-risk/{awid}/{deviceId}",async(string awid,string deviceId,IDeviceRiskRepository repo,CancellationToken ct)=>await repo.GetLatestAsync(awid,deviceId,ct) is{} p?Results.Ok(p):Results.NotFound());app.Run();public partial class Program;